(function () {
	var base = "https://omafit-nuvem-production.up.railway.app";
	window.OMAFIT_APP_URL = base;
	if (window.__omafitLegacyLoaderActive) return;
	window.__omafitLegacyLoaderActive = true;
	delete window.__omafitLegacyInit;
	var existing = document.getElementById("omafit-legacy-wrapper");
	if (existing) existing.remove();
	var script = document.createElement("script");
	script.src = base + "/storefront-legacy.min.js";
	script.async = false;
	script.setAttribute("data-omafit-legacy-loader", "1");
	(document.head || document.documentElement).appendChild(script);
})();
